<template><Modal :value="visible" :title="previous?'建立替换关系':'新增二级商户关系'" width="850" :mask-closable="false" :closable="!disabled" footer-hide @on-visible-change="v=>{if(!v&&visible)$emit('cancel')}"><div class="s1-ui"><Alert show-icon>保存只建立未核验关系，不凭输入二级商户号取得经营资格。</Alert><p v-if="previous" class="ui-meta">替换原关系 {{previous.id}}；历史关系保留。</p><Form :model="form" :label-width="150"><FormItem label="商户" required><BusinessSelect v-model="form.storeId" type="stores" :disabled="disabled||!!previous"/></FormItem><FormItem label="渠道配置" required><BusinessSelect v-model="form.configId" type="channel-configs" :disabled="disabled" @selected="config=$event"/><p v-if="config" class="ui-note">{{config.name}} · {{status(config.mode)}} · {{config.enabled?'启用':'停用'}} · v{{config.version}}</p></FormItem><FormItem label="已有二级商户号"><Input v-model="form.existingSubMchid" maxlength="64" :disabled="disabled"/><p class="ui-note">选填业务商户号；手工关联仍需后端归属和能力核验。</p></FormItem><FormItem label="关联原因" required><Input v-model="form.reason" type="textarea" maxlength="500" :rows="3" :disabled="disabled"/></FormItem></Form><p v-if="error||localError" class="ui-error">{{error||localError}}</p><footer class="ui-form-footer"><Button :disabled="busy" @click="$emit('cancel')">取消</Button><Button type="primary" :loading="busy" :disabled="disabled" @click="save">保存未核验关系</Button></footer></div></Modal></template>
<script>import accessible from '../accessibility';import BusinessSelect from './BusinessSelect';import {status} from '../display.cjs';export default {mixins:[accessible],components:{BusinessSelect},props:{visible:Boolean,previous:Object,storeId:String,disabled:Boolean,busy:Boolean,error:String},data:()=>({form:{},config:null,localError:''}),watch:{visible(value){if(value){this.config=null;this.localError='';this.form={storeId:this.previous?this.previous.storeId:this.storeId||'',configId:this.previous?this.previous.configId:'',existingSubMchid:'',reason:''};}},form:{deep:true,handler(){if(this.visible)this.$emit('dirty');}}},methods:{status,save(){if(!this.form.storeId||!this.form.configId||!String(this.form.reason||'').trim()){this.localError='请选择商户、渠道配置并填写关联原因。';return;}const body={...this.form,...(this.previous?{predecessorId:this.previous.id}:{})};if(!body.existingSubMchid)delete body.existingSubMchid;this.$emit('save',body);}}};</script>
